from lib import *
S = SS('u114')
steps = [
    step("Option<T> 的大小:u32 → Option<u32> 从 4 字节变 8(多出 tag,加上对齐),u8 → 2,f64 → 16;但 NonZeroU32、NonZeroU8、bool、char、&u64、Box<u64>、Rc<u64>、Vec<u8>、String 以及无数据的 enum Dir 的 Option 都和原类型一样大 —— 它们有「用不到的位模式」(niche),None 就用其中一个表示,不需要额外标签。", t=tl(S(1)), done=lidx(S(1), 'NonZeroU32', 'bool ', 'char ', '&u64', 'Box<u64>', 'Vec<u8>', 'String'), mark=lidx(S(1), '多出 tag'), kv=KV([['u32 / u8 / f64', 'Option 多出 tag'], ['NonZero / bool / char / 引用 / Box / Vec / String', 'Option 不加大小']], ['NonZero / bool / char / 引用 / Box / Vec / String'])),
    step("niche 可以嵌套:bool 只用了 0 和 1,Option<Option<bool>> 与 Option<Option<Option<bool>>> 仍然都是 1 字节 —— 其余 254 个位模式都能拿来区分外层的 None。", t=tl(S(1)), done=lidx(S(1), 'Option<Option<bool>>'), kv=KV([['Option<Option<Option<bool>>>', '1 字节']], ['Option<Option<Option<bool>>>'])),
    step("-Z print-type-sizes 展示带数据的枚举:Shape { Dot, Circle(f32), Rect(f32, f32), Poly([f32; 6]) } 是 28 字节、对齐 4:discriminant 4 字节 + 最大变体 Poly 24 字节;各变体从标签后面开始排,Rect 8 字节、Circle 4 字节、Dot 0 字节。", t=tl(S(2)), done=lidx(S(2), 'type: `Shape`', 'discriminant', 'variant `Poly`', 'variant `Rect`', 'variant `Circle`', 'variant `Dot`'), kv=KV([['Shape', '28 字节 = 标签 4 + Poly 24'], ['最大变体', 'Poly([f32; 6]) 24 字节']], ['Shape'])),
    step("Msg { Quit, Move { x, y }, Write(String), Color(u8, u8, u8) } 只有 24 字节,和一个 String 一样大,输出里没有 discriminant 一项:合理的推测是标签藏进了 String 里用不到的位模式(String 的容量不会取遍所有值),但本文只观察到「没有单独的标签字段、总大小等于 String」这个结果,没有验证具体用的是哪个字段;Move 与 Color 的数据前各有 8 字节 padding。", t=tl(S(2)), done=lidx(S(2), 'type: `Msg`', 'variant `Write`'), mark=lidx(S(2), 'padding: 8 bytes'), kv=KV([['Msg', '24 字节 = String 的大小'], ['标签', '无单独字段(推测用了 niche)']], ['标签'])),
    step("判别值:#[derive] 之外,C 风格枚举可以显式写值:Op::Add = 10、Sub = 20,Mul 接着前一个加 1 得 21。带数据的枚举用 mem::discriminant 比较变体:Data::A(1) 与 Data::A(99) 的 discriminant 相等(true),与 Data::B(..) 不等(false)。", t=tl(S(3)), done=lidx(S(3), 'Op::Add as i32', 'discriminant'), kv=KV([['显式判别值', 'Add = 10, Sub = 20, Mul = 21'], ['discriminant', '只比变体,不比数据']], ['discriminant'])),
    step("数字转回枚举没有内置方法:10 as Op 报 error[E0605]: non-primitive cast: `i32` as `Op`。要手写 match 或实现 TryFrom<i32>。", t=tl(S(3)), mark=lidx(S(3), 'error[E0605]'), kv=KV([['10 as Op', 'E0605']], ['10 as Op'])),
    step("niche 的真实内存(transmute 读出):Option<&u64> 的 None 是 0x0(空指针),Some 就是指针本身(非 0);Option<bool>:None = 2、Some(true) = 1、Some(false) = 0 —— 用 bool 永远不会出现的 2 当 None;没有 niche 的 Option<u32>(8 字节):None 的低 4 字节 tag = 0,Some(7) 的 tag = 1。", t=tl(S(4)), done=lidx(S(4), 'Option<&u64>', 'Option<bool>', 'Option<u32>'), kv=KV([['Option<&u64> None', '0x0'], ['Option<bool> None', '2'], ['Option<u32> None / Some', 'tag 0 / 1']], ['Option<bool> None'])),
]
A = mkart('u114', 114, 'Rust,枚举,niche,内存布局,真实验证,动画演示',
    '用 size_of、-Z print-type-sizes 与 transmute 验证枚举布局:Option<u32> 8 字节而 Option<NonZeroU32>/bool/&T/Box/String 都不加大小(niche);Option 嵌套三层 bool 仍 1 字节;Shape 28 字节(标签 4 + 最大变体 24);Msg 24 字节(与 String 一样大,没有单独的标签字段);判别值与 E0605;Option<bool> 的 None 就是 2。',
    'Option<Box<T>> 为什么和 Box<T> 一样大?枚举的标签放在哪里?什么类型有 niche?这篇用编译器自己的布局输出和 transmute 读内存,把枚举布局与空指针优化量出来。',
    [('4 字节', 'Option<NonZeroU32> 的大小(Option<u32> 是 8 字节)'), ('1 字节', 'Option<Option<Option<bool>>> 的大小'), ('24 字节', 'Msg 枚举的大小(与 String 相同,没有单独的标签)')],
    [('Option 与 niche', '<p>Option<&T> 的空指针优化见<a href="rust-option-ref-niche.html">Option&lt;&T&gt; 的空指针优化</a>。</p>'), ('带数据的枚举', '<p>布局输出用 RUSTC_BOOTSTRAP=1 -Z print-type-sizes,枚举布局不是稳定保证。repr(C) 与 repr(u8) 的区别见<a href="rust-repr-c-layout.html">#[repr(C)] 与内存布局</a>。</p>'), ('判别值', None), ('niche 的真实字节', None)],
    steps, [ENV_U + '。布局是 rustc 1.98.1 在 aarch64 上的当前结果', '没有验证:多变体枚举 niche 选择的具体规则(为什么 Msg 的标签选了 String 的容量字段,只观察到结果)、其它平台、repr(C) 枚举带数据的联合布局、枚举字段重排与大小的关系'], '枚举布局')
